import copy


def _owner(value):
    if not isinstance(value, str):
        raise TypeError("owner must be a string")
    if not value:
        raise ValueError("owner must be non-empty")
    return value


def _id(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError("id must be an integer")
    if value <= 0:
        raise ValueError("id must be positive")
    return value


def apply_actions(actions):
    if isinstance(actions, (str, bytes)):
        raise TypeError("actions must be an iterable")
    try:
        actions = list(actions)
    except TypeError:
        raise TypeError("actions must be an iterable") from None
    notes = {}
    snapshots = []
    fields = {"add": {"op", "owner", "id", "text"}, "edit": {"op", "owner", "id", "text"}, "remove": {"op", "owner", "id"}, "list": {"op", "owner"}}
    for action in actions:
        if not isinstance(action, dict):
            raise TypeError("action must be a dictionary")
        op = action.get("op")
        if not isinstance(op, str):
            raise TypeError("op must be a string")
        if op not in fields or set(action) != fields[op]:
            raise ValueError("invalid action fields")
        owner = _owner(action["owner"])
        if op == "list":
            snapshot = [notes[key] for key in sorted(notes) if notes[key]["owner"] == owner]
            snapshots.append(snapshot)
            continue
        note_id = _id(action["id"])
        if op in ("add", "edit"):
            text = action["text"]
            if not isinstance(text, str):
                raise TypeError("text must be a string")
            if not text:
                raise ValueError("text must be non-empty")
        if op == "add":
            if note_id in notes:
                raise ValueError("duplicate id")
            notes[note_id] = {"id": note_id, "owner": owner, "text": text}
        elif note_id not in notes or notes[note_id]["owner"] != owner:
            raise ValueError("note unavailable")
        elif op == "edit":
            notes[note_id]["text"] = text
        else:
            del notes[note_id]
    return {"notes": [copy.deepcopy(notes[key]) for key in sorted(notes)], "snapshots": snapshots}

